def _solve(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p):
    """X = M^{-1} R (7x8); X[i] = coeffs of (H_yy,H_yy',H_zz,H_zz',a_y,a_y',1)
    in unknown i, order (H_rr,H_xr,H_rr',H_xr',H_yy'',H_zz'',a_y'')."""
    M = np.array(_Mmat(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p), dtype=complex)
    R = np.array(_Rmat(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p), dtype=complex)
    return np.linalg.solve(M, R)


def row_hyy(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p):
    row = _solve(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p)[4]
    return ([row[0], row[2], row[4]], [row[1], row[3], row[5]], row[6])


