def c4_integrand(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p):
    """C4 = int p1 w0^4 dr, p1 = e^{W-2V}."""
    return W0**4*math.exp(-2*V)*math.exp(W)


def x_integrand(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p, ay):
    """X = int p1 bhat w0^2 dr, bhat = iG a_y (transverse)."""
    return 1j*G*W0**2*math.exp(-2*V)*math.exp(W) * ay


def pi_grav(r, U, Up, V, Vp, W, Wp, B, G, alpha, W0, W0p, hyy, hzz, ay, hrr, hxr):
    """Graviton pairing density sqrt(-g) S^{MN} h_MN (even sector);
    graviton exchange = 1/2 int pi_grav dr (plug solved fields)."""
    return (B*W0**2*hrr*math.exp(W) - B*W0**2*hyy*math.exp(W) + B*W0**2*hzz*math.exp(W) + U*W0p**2*hrr*math.exp(2*V)*math.exp(W) - U*W0p**2*hzz*math.exp(2*V)*math.exp(W))*math.exp(-2*V)

